from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    M = np.max(g)
    if S <= 0 or M <= 0:
        return 0.0
    return Q / (S * S * M)


def _grad(h):
    h = np.asarray(h, dtype=float)
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    j = int(np.argmax(g))
    M = g[j]
    if S <= 0 or M <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    w = dQdg[1:2 * N]
    conv = fftconvolve(w, h[::-1], mode='full')
    dQdh = 2.0 * conv[N - 1:2 * N - 1]
    dMdh = np.zeros(N)
    k = j - 1
    if 0 <= k <= 2 * N - 2:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        dMdh[idx] = 2.0 * h[k - idx]
    grad = dQdh / Q - 2.0 / S - dMdh / M
    return Q / (S * S * M), grad


def _resample(h, N):
    M = len(h)
    if M == N:
        return h.copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h)


def _lbfgs(h, deadline, maxiter=500):
    N = h.size

    def f(x):
        if time.process_time() > deadline:
            raise TimeoutError
        R, g = _grad(x)
        return -R, -g

    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * N,
                       options={'maxiter': maxiter, 'ftol': 1e-18, 'gtol': 1e-15,
                                'maxfun': maxiter * 5, 'maxcor': 30})
        xr = np.maximum(res.x, 0.0)
        if xr.sum() > 0:
            return xr, _R(xr)
    except Exception:
        pass
    return h, _R(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            s = np.maximum(s, 0.0)
            best_h = s / s.sum()
            best_R = _R(best_h)
        else:
            start = None

    if start is None:
        N = 10000
        best_h = np.minimum(np.arange(1, N + 1), np.arange(N, 0, -1)).astype(float)
        best_h /= best_h.sum()
        best_R = _R(best_h)

    # Progressive grid refinement: coarse -> fine. On each grid, do L-BFGS,
    # upsample, then L-BFGS again. This exploits the near-degenerate optimum
    # structure where many knots sit near the max.
    grids = [best_h.size]
    for Ng in (4000, 8000, 16000, 32000, 50000):
        if Ng != best_h.size:
            grids.append(Ng)

    for Ng in grids:
        if time.process_time() > deadline - 0.5:
            break
        h0 = _resample(best_h, Ng)
        if h0.sum() <= 0:
            continue
        h0 = np.maximum(h0, 0.0)
        h0 /= h0.sum()
        # allocate remaining time roughly evenly among remaining grids
        hg, Rg = _lbfgs(h0, deadline, maxiter=2000)
        # polish pass
        if time.process_time() < deadline - 0.3:
            hg2, Rg2 = _lbfgs(hg, deadline, maxiter=1000)
            if Rg2 > Rg:
                hg, Rg = hg2, Rg2
        if Rg > best_R:
            best_R = Rg
            best_h = hg

    # Final round of L-BFGS on the best grid to squeeze the last bits.
    if time.process_time() < deadline - 0.2:
        hf, Rf = _lbfgs(best_h, deadline, maxiter=2000)
        if Rf > best_R:
            best_R = Rf
            best_h = hf

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(1)
    print("final R =", best_R, "N =", best_h.size)
    return best_h

